import scss from './BookList.module.scss'
import { BookItem } from "../BookItem/BookItem"

export const BookList = ({showModalImage, filteredBooks}) => {


    return(
         <ul className={scss.bookList}>
        {filteredBooks.map(book => (
            <BookItem
          id={book.id}
          key={book.id}
          name={book.name}
          author={book.author}
          year={book.year}
          genre={book.genre}
          cover ={book.cover}
          image={book.cover}
          color={book.color}
          textColor={book.textColor}
          showModalImage={showModalImage}
          publishYear={book.color} publisher={book.color} pages={book.color} read={book.color} series={book.color} seriesName={book.color}volumes={book.color} part={book.color} rating={book.color}description={book.color} language={book.color}
          dateOfReading={book.color}dateOfBuying={book.color}
          />
        ))
    }
    </ul>
    )
}
